  "/dinofit/compra.css": [
    "text/css",
    "\n/* DinoFit Compra. Keep the dashboard compact; detail belongs in the editor. */\n.compra-home{--compra-edge:#8cd6b437;--compra-panel:#12221e;--compra-green:#acdfbb;--compra-ink:#e7f2e9;max-width:1010px;margin-inline:auto}\n.compra-head,.compra-board-head,.compra-modal-head,.compra-modal-foot,.compra-products-head{display:flex;align-items:center;justify-content:space-between;gap:.85rem}\n.compra-head{align-items:flex-start;border-bottom:1px solid var(--compra-edge);padding-bottom:1.05rem;margin-bottom:1.1rem}\n.compra-head h1,.compra-board-head h2,.compra-products-head h3,.compra-modal-head h2,.compra-empty p{margin:.25rem 0}\n.compra-head .eyebrow,.compra-modal-head .eyebrow{margin:0;color:#a7c8ad;letter-spacing:.12em}\n.compra-notifs{display:grid;justify-items:end;gap:.4rem}\n.compra-squircle,.compra-state,.compra-receive,.compra-trash,.compra-close,.compra-open{font:inherit;color:inherit;background:none;cursor:pointer}\n.compra-squircle{align-items:center;display:inline-flex;justify-content:center;gap:.38rem;border:1px solid #8bcd9c;border-radius:13px;padding:.45rem .65rem;line-height:1.2;color:#c4f2ce;text-align:left;min-height:40px}\n.compra-squircle:disabled{background:transparent;opacity:1;cursor:default}\n.compra-squircle svg,.compra-trash svg,.compra-thumb svg{width:1.22rem;height:1.22rem;flex:none}\n.compra-push-options{min-width:10rem;text-align:right;font-size:.8rem}\n.compra-push-options summary,.compra-legacy summary{cursor:pointer;color:#c6ddcc;text-underline-offset:.2em}\n.compra-push-options > div{display:flex;gap:.3rem;flex-wrap:wrap;justify-content:flex-end;margin-top:.35rem}\n.compra-push-status{font-size:.85rem;margin:.15rem 0 .65rem;color:#c5dcce}.compra-push-status:empty{display:none}\n.compra-board-head{margin-bottom:1rem}.compra-board-head .helper{margin:.25rem 0 0}.compra-plan-button{white-space:nowrap;min-height:42px}\n.compra-plan-button span{font-size:1.1em;margin-right:.25em}\n.compra-board{display:grid;gap:.5rem}\n.compra-card{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:.7rem;border:1px solid var(--compra-edge);border-radius:16px;padding:.8rem .9rem;background:linear-gradient(125deg,#29362e80,#0f191b)}\n.compra-open{display:block;max-width:100%;text-align:left;border:0;padding:.15rem 0;font-size:1.05rem;font-weight:750}\n.compra-open:hover{text-decoration:underline;text-underline-offset:.23em;color:var(--compra-green)}\n.compra-card-info{display:flex;flex-wrap:wrap;gap:.25rem .7rem;color:#bdcdc2;font-size:.83rem;margin-top:.13rem}\n.compra-card-info span+span::before{content:'·';margin-right:.65rem;color:#95a69b}\n.compra-card-actions{display:grid;justify-items:end;gap:.2rem;font-size:.83rem}\n.compra-state{border:1px solid #dab86b70;color:#ffe0a0;border-radius:10px;min-height:35px;padding:.25rem .62rem}\n.compra-state[aria-pressed=true]{border-color:#8bc5a86e;color:#c7f4d2}\n.compra-receive{border:0;color:#c7f4d2;min-height:34px;text-decoration:underline;text-underline-offset:.2em}\n.compra-stock-note{font-size:.78rem;color:#b1c6b6;display:block;margin-top:.3rem}\n.compra-empty{border:1px dashed var(--compra-edge);border-radius:15px;display:grid;justify-items:center;text-align:center;gap:.18rem;padding:1.65rem .85rem;color:#cbdccf}\n.compra-empty svg{width:1.65rem;height:1.65rem;color:var(--compra-green);margin-bottom:.35rem}\n.compra-empty p,.compra-time{font-size:.86rem;color:#afc5b8}\n.compra-dialog{width:min(45rem,calc(100% - 1.4rem));max-width:100%;max-height:calc(100dvh - 1.4rem);overflow:auto;border:1px solid #93cca267;border-radius:20px;padding:0;box-sizing:border-box;color:var(--compra-ink);background:#10201b;box-shadow:0 16px 64px #030706b8;color-scheme:dark}\n.compra-dialog::backdrop{background:rgba(4,10,9,.70);backdrop-filter:blur(3px)}\n.compra-modal-head,.compra-modal-foot{background:#142621;padding:.8rem 1rem;position:sticky;z-index:1;box-shadow:0 0 0 1px var(--compra-edge)}\n.compra-modal-head{top:0}.compra-modal-foot{bottom:0;padding-bottom:max(.8rem,env(safe-area-inset-bottom))}\n.compra-modal-body{padding:.9rem 1rem}\n.compra-close,.compra-trash{display:grid;place-items:center;border:1px solid var(--compra-edge);border-radius:10px;min-width:40px;min-height:40px;font-size:1.5rem}\n.compra-trash{color:#ffd4c7}\n.compra-period,.compra-legacy{border:1px solid var(--compra-edge);border-radius:12px;padding:.7rem}\n.compra-legacy{margin-top:1rem}\n.compra-period summary{color:var(--compra-ink);font-weight:700;cursor:pointer}\n.compra-period summary span{font-size:.85rem;font-weight:500;color:#b6d4bf;margin-left:.4rem}\n.compra-dates,.compra-item{display:grid;align-items:end;gap:.6rem}\n.compra-dates{grid-template-columns:repeat(auto-fit,minmax(min(100%,9.7rem),1fr));margin:.6rem 0}\n.compra-dates label,.compra-item label{display:grid;gap:.25rem;font-size:.8rem;min-width:0}\n.compra input:not([type=checkbox]){min-width:0;width:100%;box-sizing:border-box;color:inherit;background:#172a23;border:1px solid #759a8177;border-radius:9px;padding:.48rem .5rem;color-scheme:dark;font-size:16px}\n.compra time,.compra input[type=date]{min-height:36px}\n.compra-item{grid-template-columns:42px minmax(0,1fr) minmax(62px,.3fr) minmax(68px,.36fr) 40px;padding:.52rem;margin:.55rem 0 0;border:1px solid var(--compra-edge);border-radius:12px;min-width:0}\n.compra-thumb{position:relative;display:grid;place-items:center;width:42px;height:42px;border-radius:9px;color:#a6c6b2;background:#293e34;border:1px solid #436252}\n.compra-thumb img{position:absolute;inset:0;object-fit:contain;display:block;width:100%;height:100%;border-radius:inherit;background:#fff}\n.compra-thumb img[hidden]{display:none}.compra-line-total{grid-column:2 / -1;text-align:right;font-size:.76rem;color:#abc4b4;margin-top:-.25rem}\n.compra-actions{display:flex;flex-wrap:wrap;gap:.4rem;justify-content:flex-end}.compra-actions button{font-size:.79rem;min-height:37px}\n.compra-products-head{margin-top:.9rem}.compra-total{display:grid;gap:.15rem;font-size:.75rem;color:#c1d3c7}\n.compra-total output{font-size:1.05rem;font-weight:800;color:var(--compra-ink)}\n.compra-form-error{color:#ffd4ba;margin-bottom:.3rem}.compra-receipt{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.15rem .6rem;margin-top:.8rem;color:#c3dcce}.compra-receipt small{flex-basis:100%}\n.compra :is(button,input,summary):focus-visible{outline:2px solid #98e0ad;outline-offset:2px}\n.compra .compra-check{display:flex;gap:.45rem;align-items:center;align-self:center}\n.compra-occur{border:1px solid var(--compra-edge);border-radius:10px;padding:.5rem;margin-block:.5rem}\n@media(max-width:530px){\n .compra-home .eyebrow{font-size:.63rem}.compra-head,.compra-board-head{gap:.4rem}\n .compra-squircle{font-size:.71rem}.compra-squircle svg{width:.98rem;height:.98rem}\n .compra-board-head .helper{display:none}.compra-plan-button{font-size:.8rem;padding-inline:.55rem}\n .compra-card{padding:.62rem;gap:.38rem}.compra-open{font-size:.95rem}.compra-card-info{font-size:.74rem;gap:.16rem .34rem}.compra-card-info span+span::before{margin-right:.35rem}\n .compra-card-actions{font-size:.73rem}.compra-state{min-height:38px}\n .compra-modal-body,.compra-modal-head,.compra-modal-foot{padding-inline:.64rem}\n .compra-item{grid-template-columns:37px minmax(45px,1fr) minmax(50px,1fr) 40px;gap:.36rem}.compra-thumb{width:35px;height:35px;align-self:center;grid-row:1}\n .compra-item .compra-item-name{grid-column:2/-1}.compra-item-qty{grid-column:1/3}.compra-item-price{grid-column:3}.compra-trash{grid-column:4}\n .compra-line-total{grid-column:1/-1}.compra-products-head{display:grid;justify-content:stretch;gap:.45rem}.compra-actions{justify-content:flex-start}\n}\n"
  ],
